// PreToolUse hook: blocks Edit/Write to generated/build-output files so they
// don't get hand-edited and silently overwritten by the next build/script.
//
//   src/content/shop/products.json  -> generated by scripts/parse-shop.mjs
//   dist/**                          -> `astro build` output
//   .astro/**                        -> Astro's generated types/cache
//
// Reads the hook payload as JSON on stdin, emits a PreToolUse "deny" decision
// when the target path is generated, and stays silent (allow) otherwise.

let raw = '';
process.stdin.on('data', (d) => (raw += d));
process.stdin.on('end', () => {
  let path = '';
  try {
    path = JSON.parse(raw)?.tool_input?.file_path ?? '';
  } catch {
    // Malformed payload — don't block on parse errors.
    process.exit(0);
  }

  // Normalise Windows backslashes so the patterns match on either OS.
  const p = path.replace(/\\/g, '/');

  const isGenerated =
    /(^|\/)dist\//.test(p) ||
    /(^|\/)\.astro\//.test(p) ||
    /(^|\/)src\/content\/shop\/products\.json$/.test(p);

  if (!isGenerated) process.exit(0);

  const reason =
    /products\.json$/.test(p)
      ? 'src/content/shop/products.json is GENERATED by `node scripts/parse-shop.mjs` from ' +
        'src/assets/text_for_shop_products/. Edit the source .txt and re-run the script instead.'
      : 'This is build output (dist/ or .astro/) — regenerate it with `npm run build` / `astro sync` ' +
        'rather than editing it by hand.';

  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'deny',
        permissionDecisionReason: reason,
      },
    }),
  );
  process.exit(0);
});
